# ---------------- Ch10 Circles
C,CN='circles','Circles'
B(C,CN,'tangent-to-a-circle','Tangent to a circle',
 "The wheel and the road",
 "A bicycle wheel touches the road at just one point. That line touching a circle at one point is called a tangent.",
 [("A tangent to a circle is a line that meets the circle at exactly one point, called the point of contact.","tangent"),
  ("A secant is a line that cuts the circle at two points.","secant"),
  ("Theorem one: the tangent at any point of a circle is perpendicular to the radius through the point of contact.","tangent perpendicular to radius"),
  ("So a tangent makes a right angle with the radius at the point where it touches.","90 degrees"),
  ("At any point on a circle there is one and only one tangent.","one tangent"),
  ("The perpendicular to a tangent at its point of contact passes through the centre of the circle.","passes through centre"),
  ("Example: radius OP = 5 and OQ = 13 where PQ is a tangent at P. Then PQ = root(169 - 25) = 12.","PQ = 12"),
  ("The proof is by contradiction: if OP were not perpendicular, a closer point on the tangent would lie inside the circle.","proof idea")],
 ("A tangent PQ at point P of a circle with centre O meets OQ at Q. If OP = 3 cm and OQ = 5 cm, find PQ.",[("OP is perpendicular to PQ, so triangle OPQ is right angled at P.","Tangent is perpendicular to the radius."),("PQ^2 = OQ^2 - OP^2 = 25 - 9 = 16.","Pythagoras."),("PQ = 4 cm.","Square root.")]),
 ("What is special about a tangent and the radius?",["Tangent meets circle at one point","Perpendicular to the radius","Pythagoras helps"],["Thinking the tangent passes through the centre"]),
 ["A tangent touches the circle at exactly one point.","The tangent is perpendicular to the radius at the point of contact.","Use Pythagoras with the radius, tangent and line from the centre."],
 [mcq("r1-tc1",1,"A line meeting a circle at exactly one point is a","tangent",[("secant","A secant meets it at two points."),("chord","A chord joins two points.")],"Tangent."),
  tf("r1-tc2",1,"The tangent at a point of a circle is perpendicular to the radius at that point.",True,"Theorem 10.1."),
  num("r2-tc3",2,"OP = 5, tangent PQ = 12, find OQ",13,"root(25 + 144) = 13.",[(17,"Use Pythagoras.")]),
  mcq("r2-tc4",2,"Assertion (A): Number of tangents at a point of a circle is one. Reason (R): Two tangents at the same point would both have to be perpendicular to the radius.",A,[("A true, R false","R is correct."),("A false, R true","Hence only one.")],"Only one perpendicular line exists."),
  num("r2-tc5",2,"Angle between tangent and the radius at contact point (degrees)",90,"Perpendicular.",[(180,"A straight angle.")]),
  mcq("r3-tc6",3,"Case study: A wheel of radius 14 cm touches a straight road. The distance from the centre of the wheel to the road is","14 cm",[("28 cm","That is the diameter."),("7 cm","Half the radius.")],"Radius is perpendicular to the tangent."),
  tf("r3-tc7",3,"A circle can have infinitely many tangents.",True,"One at each point."),
  num("r3-tc8",3,"Radius 7, distance of a point from the centre 25. Length of tangent",24,"root(625 - 49) = 24.",[(18,"Square both and subtract.")])])
B(C,CN,'tangents-from-an-external-point','Tangents from an external point',
 "Two ropes, one pole",
 "From a point outside a circle we can draw exactly two tangents, and they have a beautiful property: their lengths are equal.",
 [("From a point inside a circle there is no tangent. From a point on the circle there is one tangent.","how many tangents"),
  ("From a point outside the circle there are exactly two tangents.","two tangents"),
  ("Theorem two: the lengths of the tangents drawn from an external point to a circle are equal.","equal tangents"),
  ("Proof: join OP, OQ and OR. Triangles OPQ and OPR are right triangles with OQ = OR and a common hypotenuse OP, so they are congruent by RHS.","RHS congruence"),
  ("Hence PQ = PR. The line OP also bisects the angle between the tangents.","OP bisects angle"),
  ("Example: tangents PA and PB from P with angle APB = 80 degrees. Then angle OAP = 90 and angle AOB = 100.","angle AOB = 100"),
  ("In a circle touching all sides of a quadrilateral, the sum of the opposite sides is equal: AB + CD = AD + BC.","AB + CD = AD + BC"),
  ("Use equal tangents to set up equations in lengths and angles.","use equal tangents")],
 ("Two tangents PA and PB are drawn from P to a circle with centre O. If angle APB = 70 degrees, find angle AOB.",[("OA and OB are perpendicular to PA and PB, so angle OAP = angle OBP = 90.","Tangent-radius."),("In quadrilateral OAPB, angle AOB = 360 - 90 - 90 - 70.","Angle sum is 360."),("Angle AOB = 110 degrees.","Compute.")]),
 ("State the theorem about tangents from an external point.",["Two tangents","Equal lengths","Proof by RHS"],["Believing tangents from a point can be unequal"]),
 ["From an external point, two tangents can be drawn and they are equal in length.","The line joining the point to the centre bisects the angle between them.","In a quadrilateral around a circle, sums of opposite sides are equal."],
 [mcq("r1-te1",1,"The number of tangents from an external point is","2",[("1","One is from a point on the circle."),("0","That is for an inside point.")],"Two."),
  num("r1-te2",1,"PA = 7 cm is a tangent length from P. PB (the other tangent) =",7,"Equal tangents.",[(14,"Not doubled.")]),
  num("r2-te3",2,"Angle APB = 60 degrees, find angle AOB",120,"360 - 180 - 60 = 120.",[(30,"Check the quadrilateral.")]),
  mcq("r2-te4",2,"Assertion (A): Tangents from an external point are equal. Reason (R): Triangles OPQ and OPR are congruent by RHS.",A,[("A true, R false","R is the proof."),("A false, R true","The tangents are equal.")],"RHS gives PQ = PR."),
  num("r2-te5",2,"Quadrilateral ABCD circumscribes a circle, AB = 6, CD = 4, AD = 5. Find BC",5,"AB + CD = AD + BC so 10 = 5 + BC.",[(3,"Add AB and CD first.")]),
  mcq("r3-te6",3,"The centre O, point P and tangent points A, B: the line OP","bisects angle APB",[("is perpendicular to AB at P","It meets AB at its midpoint, not at P."),("is parallel to AB","It is perpendicular to AB.")],"Congruent triangles."),
  tf("r3-te7",3,"The perimeter of a triangle formed by two tangents and a third tangent is twice the tangent length from the vertex.",True,"Equal tangent lengths add up."),
  num("r3-te8",3,"PA = PB, angle PAB = 50 degrees. Angle APB (degrees)",80,"180 - 50 - 50.",[(100,"Angle sum of triangle.")])])
